const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const insert = db.prepare(\`
  INSERT INTO ob_calendar_events (username, summary, dtstart, dtend, dtstamp, description, location)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

const summary = 'Onboarding Equipment Setup — New Contractor';
const dtstart = '2026-09-09T09:00:00';
const dtend = '2026-09-09T10:00:00';
const dtstamp = '2026-09-08T10:00:00';
const description = 'High-priority onboarding equipment setup for newly onboarded contractor. Tasks:\\n\\n1. Laptop: Provision and configure a standard Windows laptop\\n2. VPN: Set up VPN access credentials and verify connectivity\\n3. Email: Configure corporate email account and confirm functionality\\n\\nAll items must be completed before start of business. Setup ticket should be tracked and confirmed by Priya (IT Lead).\\n\\nRef: Follow-up email from Olivia (HR Manager) to Priya (IT Lead).';
const location = '';

const result = insert.run('priya.it.lead', summary, dtstart, dtend, dtstamp, description, location);
console.log('Inserted event_id:', result.lastInsertRowid);

// Verify
const row = db.prepare('SELECT * FROM ob_calendar_events WHERE event_id = ?').get(result.lastInsertRowid);
console.log(JSON.stringify(row, null, 2));
"

