node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const subject = 'Confirmation: Onboarding Equipment Setup Scheduled — September 9, 2026';
const from_address = 'priya.it.lead@company.com';
const to_address = 'ethan.it.specialist@company.com';
const content = \`Hello Ethan,

I'm writing to confirm that the onboarding equipment setup for the new contractor has been scheduled and will be tracked on September 9, 2026.

Please ensure the following items are prepared and completed before start of business that day:

1. Laptop: Provision and configure a standard Windows laptop
2. VPN: Set up VPN access credentials and verify connectivity
3. Email: Configure a corporate email account and confirm functionality

A calendar event has been created to track this task. If you have any questions or anticipate any issues with the timeline, please let me know as soon as possible so we can address them promptly.

Thank you for your support on this.

Best regards,
Priya\`;

const insert = db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

// Sender copy (priya's sent/inbox)
insert.run(
  'priya.it.lead/' + subject + '.eml',
  'priya.it.lead',
  from_address,
  to_address,
  subject,
  content,
  'priya.it.lead'
);

// Recipient copy (ethan's inbox)
insert.run(
  'ethan.it.specialist/' + subject + '.eml',
  'ethan.it.specialist',
  from_address,
  to_address,
  subject,
  content,
  'ethan.it.specialist'
);

// Verify
const rows = db.prepare(\"SELECT email_id, from_address, to_address, subject, content, inbox_owner FROM ob_emails WHERE subject LIKE '%Confirmation%September 9%'\").all();
console.log(JSON.stringify(rows, null, 2));
"
